-- Local-only wizard matching snapshot extracted from linked development project on 2026-10-02.
-- 190 stations/codes, 396 provider aliases, 17 templates, 161 template configs,
-- 93 station recognitions, 5 combined algorithms, 9 algorithm steps, 27 algorithm codes.
-- Company UUIDs are resolved by name; station/template/algorithm IDs map to local natural keys.
BEGIN;

CREATE TEMP TABLE seed_stations_src (
  source_id uuid PRIMARY KEY, peaje_id uuid NOT NULL, nombre text NOT NULL, ubicacion text,
  descripcion text, codigos_proveedor text[] NOT NULL DEFAULT '{}', created_at timestamptz,
  latitud numeric, longitud numeric, camino text, estado_geocodificacion text
) ON COMMIT DROP;







-- Collapse repeated source station names; the source contains five duplicate JUNIN/Ruta 188 rows.
SELECT DISTINCT ON (s.peaje_id,s.nombre)
       s.source_id,s.peaje_id,s.nombre,s.ubicacion,s.descripcion,s.codigos_proveedor,s.created_at,
       s.latitud,s.longitud,s.camino,s.estado_geocodificacion
FROM seed_stations_src s
WHERE NOT EXISTS (SELECT 1 FROM public.estaciones e WHERE e.peaje_id=s.peaje_id AND e.nombre=s.nombre)
ORDER BY s.peaje_id,s.nombre,s.source_id
ON CONFLICT (id) DO UPDATE SET
  peaje_id=EXCLUDED.peaje_id,nombre=EXCLUDED.nombre,ubicacion=EXCLUDED.ubicacion,
  descripcion=EXCLUDED.descripcion,codigos_proveedor=EXCLUDED.codigos_proveedor,
  latitud=EXCLUDED.latitud,longitud=EXCLUDED.longitud,camino=EXCLUDED.camino,
  estado_geocodificacion=EXCLUDED.estado_geocodificacion;

UPDATE public.estaciones e
SET ubicacion=s.ubicacion,descripcion=s.descripcion,codigos_proveedor=s.codigos_proveedor,
    latitud=s.latitud,longitud=s.longitud,camino=s.camino,estado_geocodificacion=s.estado_geocodificacion
FROM (SELECT DISTINCT ON (peaje_id,nombre) * FROM seed_stations_src ORDER BY peaje_id,nombre,source_id) s
WHERE e.peaje_id=s.peaje_id AND e.nombre=s.nombre;

CREATE TEMP TABLE seed_station_id_map ON COMMIT DROP AS
SELECT s.source_id,
       (SELECT e.id FROM public.estaciones e
        WHERE e.peaje_id=s.peaje_id AND e.nombre=s.nombre
        ORDER BY (e.id=s.source_id) DESC,e.created_at,e.id LIMIT 1) AS local_id
FROM seed_stations_src s;

-- Source company UUIDs can differ from local UUIDs when the development seed
-- encounters an existing company by its unique name. Resolve matching rows by name.
CREATE TEMP TABLE seed_empresas_src (source_id text PRIMARY KEY,nombre text NOT NULL) ON COMMIT DROP;

SELECT s.source_id::uuid,s.nombre
FROM seed_empresas_src s
WHERE NOT EXISTS (SELECT 1 FROM public.empresas e WHERE e.nombre=s.nombre)
ON CONFLICT (id) DO NOTHING;

CREATE TEMP TABLE seed_empresa_id_map ON COMMIT DROP AS
SELECT s.source_id,e.id::text AS local_id
FROM seed_empresas_src s JOIN public.empresas e ON e.nombre=s.nombre;

DO $$
BEGIN
  IF (SELECT count(*) FROM seed_empresa_id_map) <> (SELECT count(*) FROM seed_empresas_src) THEN
    RAISE EXCEPTION 'No se pudieron mapear todas las empresas del snapshot de Peajes';
  END IF;
END;
$$;

-- Keep the seed peajes aligned with the local company UUIDs too; alias validation
-- requires peajes.empresa_id and estaciones_alias_proveedor.empresa_id to agree.
UPDATE public.peajes p
SET empresa_id=em.local_id
FROM seed_empresa_id_map em
WHERE p.empresa_id=em.source_id AND p.empresa_id IS DISTINCT FROM em.local_id;

CREATE TEMP TABLE seed_aliases_src (
  id uuid PRIMARY KEY,empresa_id text NOT NULL,source_estacion_id uuid NOT NULL,
  valor_proveedor text NOT NULL,valor_normalizado text NOT NULL,origen text NOT NULL,created_at timestamptz
) ON COMMIT DROP;














SELECT DISTINCT ON (em.local_id,m.local_id,a.valor_normalizado)
       em.local_id,m.local_id,a.valor_proveedor,a.valor_normalizado,a.origen,a.created_at
FROM seed_aliases_src a
JOIN seed_empresa_id_map em ON em.source_id=a.empresa_id
JOIN seed_station_id_map m ON m.source_id=a.source_estacion_id AND m.local_id IS NOT NULL
ORDER BY em.local_id,m.local_id,a.valor_normalizado,(a.origen='usuario') DESC,a.created_at DESC,a.id
ON CONFLICT (empresa_id,estacion_id,valor_normalizado) DO UPDATE SET
  valor_proveedor=EXCLUDED.valor_proveedor,origen=EXCLUDED.origen,created_at=EXCLUDED.created_at;

CREATE TEMP TABLE seed_templates_src (
  source_id uuid PRIMARY KEY,nombre text NOT NULL,descripcion text,empresa_id text NOT NULL,
  estrategia_codigo text,estado text NOT NULL,created_at timestamptz,updated_at timestamptz,mapeos jsonb NOT NULL
) ON COMMIT DROP;

-- Reconcile natural-key matches first, then source-ID matches. Local migration
-- fixtures can already own a source UUID but retain a different empresa UUID.
UPDATE public.plantillas_configuracion p
SET descripcion=s.descripcion,estrategia_codigo=s.estrategia_codigo,estado=s.estado,
    created_at=s.created_at,updated_at=s.updated_at,mapeos=s.mapeos
FROM seed_templates_src s
JOIN seed_empresa_id_map em ON em.source_id=s.empresa_id
WHERE p.nombre=s.nombre AND p.empresa_id=em.local_id;

UPDATE public.plantillas_configuracion p
SET nombre=s.nombre,descripcion=s.descripcion,empresa_id=em.local_id,
    estrategia_codigo=s.estrategia_codigo,estado=s.estado,
    created_at=s.created_at,updated_at=s.updated_at,mapeos=s.mapeos
FROM seed_templates_src s
JOIN seed_empresa_id_map em ON em.source_id=s.empresa_id
WHERE p.id=s.source_id
  AND NOT EXISTS (
    SELECT 1 FROM public.plantillas_configuracion target
    WHERE target.nombre=s.nombre AND target.empresa_id=em.local_id AND target.id<>p.id
  );

SELECT s.source_id,s.nombre,s.descripcion,em.local_id,s.estrategia_codigo,s.estado,
       s.created_at,s.updated_at,s.mapeos
FROM seed_templates_src s
JOIN seed_empresa_id_map em ON em.source_id=s.empresa_id
WHERE NOT EXISTS (
  SELECT 1 FROM public.plantillas_configuracion p
  WHERE p.nombre=s.nombre AND p.empresa_id=em.local_id
)
AND NOT EXISTS (
  SELECT 1 FROM public.plantillas_configuracion p WHERE p.id=s.source_id
);

CREATE TEMP TABLE seed_template_id_map ON COMMIT DROP AS
SELECT s.source_id,p.id AS local_id
FROM seed_templates_src s
JOIN seed_empresa_id_map em ON em.source_id=s.empresa_id
JOIN public.plantillas_configuracion p ON p.nombre=s.nombre AND p.empresa_id=em.local_id;

CREATE TEMP TABLE seed_algorithms_src (
  source_id uuid PRIMARY KEY,nombre text NOT NULL,descripcion text,empresa_id text NOT NULL,
  estado text NOT NULL,created_at timestamptz,updated_at timestamptz
) ON COMMIT DROP;

UPDATE public.algoritmos_combinados a
SET descripcion=s.descripcion,estado=s.estado,created_at=s.created_at,updated_at=s.updated_at
FROM seed_algorithms_src s
JOIN seed_empresa_id_map em ON em.source_id=s.empresa_id
WHERE a.nombre=s.nombre AND a.empresa_id=em.local_id;

UPDATE public.algoritmos_combinados a
SET nombre=s.nombre,descripcion=s.descripcion,empresa_id=em.local_id,
    estado=s.estado,created_at=s.created_at,updated_at=s.updated_at
FROM seed_algorithms_src s
JOIN seed_empresa_id_map em ON em.source_id=s.empresa_id
WHERE a.id=s.source_id
  AND NOT EXISTS (
    SELECT 1 FROM public.algoritmos_combinados target
    WHERE target.nombre=s.nombre AND target.empresa_id=em.local_id AND target.id<>a.id
  );

SELECT s.source_id,s.nombre,s.descripcion,em.local_id,s.estado,s.created_at,s.updated_at
FROM seed_algorithms_src s
JOIN seed_empresa_id_map em ON em.source_id=s.empresa_id
WHERE NOT EXISTS (
  SELECT 1 FROM public.algoritmos_combinados a
  WHERE a.nombre=s.nombre AND a.empresa_id=em.local_id
)
AND NOT EXISTS (
  SELECT 1 FROM public.algoritmos_combinados a WHERE a.id=s.source_id
);

CREATE TEMP TABLE seed_algorithm_id_map ON COMMIT DROP AS
SELECT s.source_id,a.id AS local_id
FROM seed_algorithms_src s
JOIN seed_empresa_id_map em ON em.source_id=s.empresa_id
JOIN public.algoritmos_combinados a ON a.nombre=s.nombre AND a.empresa_id=em.local_id;

CREATE TEMP TABLE seed_algorithm_steps_src (
  source_id uuid PRIMARY KEY,source_algorithm_id uuid NOT NULL,orden integer NOT NULL,
  algoritmo_codigo text NOT NULL,parametros jsonb
) ON COMMIT DROP;

ON CONFLICT (codigo) DO UPDATE SET descripcion=EXCLUDED.descripcion,activo=EXCLUDED.activo;

DELETE FROM public.algoritmo_combinado_pasos
WHERE algoritmo_combinado_id IN (SELECT local_id FROM seed_algorithm_id_map);
SELECT m.local_id,s.orden,s.algoritmo_codigo,s.parametros
FROM seed_algorithm_steps_src s JOIN seed_algorithm_id_map m ON m.source_id=s.source_algorithm_id
ON CONFLICT (algoritmo_combinado_id,orden) DO UPDATE SET
  algoritmo_codigo=EXCLUDED.algoritmo_codigo,parametros=EXCLUDED.parametros;

CREATE TEMP TABLE seed_configs_src (
  source_id uuid PRIMARY KEY,source_template_id uuid NOT NULL,nombre_columna text NOT NULL,
  columna_destino text,orden integer NOT NULL,tipo text NOT NULL,
  source_algorithm_id uuid,configuracion jsonb,obligatoria boolean NOT NULL
) ON COMMIT DROP;






DELETE FROM public.configuraciones_plantilla WHERE plantilla_id IN (SELECT local_id FROM seed_template_id_map);
SELECT tm.local_id,c.nombre_columna,c.columna_destino,c.orden,c.tipo,am.local_id,c.configuracion,c.obligatoria
FROM seed_configs_src c
JOIN seed_template_id_map tm ON tm.source_id=c.source_template_id
LEFT JOIN seed_algorithm_id_map am ON am.source_id=c.source_algorithm_id
WHERE c.source_algorithm_id IS NULL OR am.local_id IS NOT NULL;

CREATE TEMP TABLE seed_recognized_src (
  source_id uuid PRIMARY KEY,source_template_id uuid NOT NULL,source_estacion_id uuid NOT NULL,
  valor_proveedor text NOT NULL,valor_normalizado text NOT NULL,origen text NOT NULL,created_at timestamptz
) ON COMMIT DROP;




DELETE FROM public.plantilla_estaciones_reconocidas WHERE plantilla_id IN (SELECT local_id FROM seed_template_id_map);
SELECT tm.local_id,sm.local_id,r.valor_proveedor,r.valor_normalizado,r.origen,r.created_at
FROM seed_recognized_src r
JOIN seed_template_id_map tm ON tm.source_id=r.source_template_id
JOIN seed_station_id_map sm ON sm.source_id=r.source_estacion_id AND sm.local_id IS NOT NULL
ON CONFLICT (plantilla_id,valor_normalizado) DO UPDATE SET
  estacion_id=EXCLUDED.estacion_id,valor_proveedor=EXCLUDED.valor_proveedor,
  origen=EXCLUDED.origen,created_at=EXCLUDED.created_at;

COMMIT;

